// Function to validate the input
func isValidInput(input string) bool {
	// Here we consider a valid input to contain only alphabets and spaces
	for _, char := range input {
		if !((char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z') || char == ' ') {
			return false
		}
	}
	return true
}

